// Extract and normalize news data from various sources
const data = $json;

const newsItem = {
  ticker: data.ticker || data.symbol || 'UNKNOWN',
  title: data.title || data.headline || '',
  summary: data.summary || data.description || '',
  source: data.source || data.publisher || 'Unknown',
  url: data.url || data.link || '',
  published_at: data.published_utc || data.publishedAt || new Date().toISOString(),
  sentiment: data.sentiment || 'neutral',
  relevance_score: data.relevance_score || 0.5,
  raw_data: JSON.stringify(data)
};

return newsItem;

// Check if ticker is in user's portfolio
const ticker = $json.ticker;
const portfolio = $json.portfolio || [];

const holding = portfolio.find(h => h.ticker === ticker);
const in_portfolio = !!holding;
const shares_owned = holding ? holding.quantity : 0;
const position_value = holding ? holding.value : 0;

return {
  ...prev.$json,
  in_portfolio: in_portfolio,
  shares_owned: shares_owned,
  position_value: position_value,
  is_priority: in_portfolio ? 'HIGH' : 'MEDIUM'
};

