// Extract Claude's analysis
const analysis_text = $json.content[0].text;
const ticker = $json.ticker;
const in_portfolio = $json.in_portfolio;

// Parse sentiment from analysis
let impact = 'NEUTRAL';
let recommendation = 'MONITOR';
let risk_level = 'MEDIUM';

if (analysis_text.includes('BULLISH')) impact = 'BULLISH';
if (analysis_text.includes('BEARISH')) impact = 'BEARISH';
if (analysis_text.includes('BUY')) recommendation = 'BUY';
if (analysis_text.includes('SELL')) recommendation = 'SELL';
if (analysis_text.includes('HIGH')) risk_level = 'HIGH';
if (analysis_text.includes('LOW')) risk_level = 'LOW';

return {
  ...prev.$json,
  impact: impact,
  recommendation: recommendation,
  risk_level: risk_level,
  analysis: analysis_text,
  alert_priority: in_portfolio ? 'CRITICAL' : 'HIGH'
};

// Generate alert message for Telegram
const data = $json;
const emoji = {
  'BULLISH': '📈',
  'BEARISH': '📉',
  'NEUTRAL': '➡️'
};

const priority_emoji = {
  'CRITICAL': '🚨',
  'HIGH': '⚠️'
};

const message = `
${priority_emoji[data.alert_priority] || '⚠️'} BREAKING NEWS ALERT

${emoji[data.impact]} ${data.impact} | ${data.recommendation}

Ticker: ${data.ticker}
Title: ${data.title}

📊 Analysis:
${data.analysis}

Source: ${data.source}
🔗 Read: ${data.url}

Risk Level: ${data.risk_level}
${data.in_portfolio ? `Portfolio Position: ${data.shares_owned} shares (£${data.position_value})` : 'Not in your portfolio'}
`;

return {
  ...data,
  alert_message: message,
  timestamp: new Date().toISOString()
};
